const MAX_LENGTH = 200

/**
 * The only reasons a reference is refused: an unknown type, nothing entered,
 * or too long to be a reference. A value that fails its check is not one of
 * them (see keepReference).
 */
export function referenceInputError(kindKey: string, raw: string): string | null {
  if (!referenceKind(kindKey)) return `Unknown reference type “${kindKey}”.`
  const trimmed = (raw ?? '').trim()
  if (!trimmed) return 'Enter the reference.'
  if (trimmed.length > MAX_LENGTH) return `That’s longer than ${MAX_LENGTH} characters.`
  return null
}

/**
 * What is saved for a reference. The practice's rule: a reference that fails
 * its check is kept as entered and flagged, never refused, because the
 * practice may hold one that is right and the check that is wrong (or one
 * that is wrong and still the one on HMRC's letters).
 *
 *   value    the tidy form when it passes; otherwise what was typed, trimmed
 *   warning  a note for a value that passes but looks unusual
 *   problem  why it fails its check, or null when it passes
 */
export interface KeptReference {
  value: string
  warning: string | null
  problem: string | null
}

export function keepReference(raw: string, check: (raw: string) => ReferenceCheckResult): KeptReference {
  const r = check(raw)
  if (r.ok) return { value: r.value, warning: r.warning ?? null, problem: null }
  return { value: raw.trim().replace(/\s+/g, ' '), warning: null, problem: r.error }
}

/** The note kept with a reference that fails its check. */
export const keptAsEnteredNote = (problem: string): string => `${problem} Kept as entered, and flagged under Issues.`

